import { registerTeamTools } from './team-tools.js';
import { projectTool } from './tool.js';
export const name = 'project-coordinator';
export const inject = ['tools', 'systemPrompt'];
export function apply(ctx) {
  ctx.tools.presentAs('native');
  registerTeamTools(ctx);
  ctx.tools.guard(exec => {
    const service = ctx.get('projects');
    return service?.available ? service.guard(exec) : 'Project Host is unavailable.';
  });
  projectTool(ctx, { name: 'project_request', method: 'acceptRequest', description: 'Record one human goal, restrictions, completion conditions and original authorization ceiling. Use disposition discussing for tentative ideas: they cannot execute. Use queued only when the user authorized development; the host activates one requirement at a time. Use requestId to revise the same goal, preserving its queue position and effective restrictions. Only actual human input creates or revises requirements. No user form or extra confirmation is needed.', parameters: { requestId: { type: 'string' }, disposition: { type: 'string', enum: ['discussing', 'queued'] }, title: { type: 'string', required: true }, goal: { type: 'string', required: true }, constraints: { type: 'array', items: { type: 'string' } }, conditions: { type: 'array', items: { type: 'string' }, required: true }, scopeCeiling: { type: 'string', enum: ['readonly', 'docs', 'development'], required: true }, writePaths: { type: 'array', items: { type: 'string' } } } });
  projectTool(ctx, { name: 'project_queue', method: 'queueRequest', description: 'Apply the human user’s queue instruction to an existing requirement. enqueue approves a discussed or cancelled goal, or explicitly rejoins a released historical goal that needs review; it preserves Project pause. move changes only waiting order (beforeRequestId, or end when absent). cancel stops that requirement and its owned work while retaining records. resume explicitly continues only the actual current requirement, or the first queued requirement when none is active; it never resumes a cancelled or released historical goal. Supply the current revision. Settlements and host queue messages cannot authorize queue changes.', parameters: { requestId: { type: 'string', required: true }, requestRevision: { type: 'number', required: true }, action: { type: 'string', enum: ['enqueue', 'move', 'cancel', 'resume'], required: true }, beforeRequestId: { type: 'string' } } });
  projectTool(ctx, { name: 'project_deliver', method: 'deliver', description: 'Explicitly declare a handover for one current requirement version, then give its final user-facing reply in this turn. Read reports first and reference their exact workstream/delegation/report identity. completed requires all necessary work, matching native settlements and validation; partial preserves explicit unmet conditions. Progress messages and reading reports never count as a handover. The host binds the real reply only after durable successful turn completion.', parameters: { requestId: { type: 'string', required: true }, requestRevision: { type: 'number', required: true }, summary: { type: 'string', required: true }, outcome: { type: 'string', enum: ['completed', 'partial'], required: true }, decision: { type: 'string', description: 'One or two sentences: what was decided or changed and why, including any user-approved exception to Project rules. Appended to the Project decision log.' }, evidence: { type: 'array', items: { type: 'string' } }, remainingIssues: { type: 'array', items: { type: 'string' } }, reportRefs: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { workstreamId: { type: 'string', required: true }, delegationRef: { type: 'string', required: true }, reportId: { type: 'string' } } } }, terminalRefs: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { workstreamId: { type: 'string', required: true }, delegationRef: { type: 'string', required: true }, runId: { type: 'string', required: true } } } } } });
  projectTool(ctx, { name: 'project_read_store', method: 'readStoreTool', description: 'Read notes.md, preferences.md, charter.md, decisions.md or docs/<path> in this Project. notes returns authoritative Project facts (bound repository versus materials directory), prior requirements, work, handovers and pending results. Empty records mean no saved Project history, not an empty repository. Repository contents require delegated inspection; no repository or internal access here.', parameters: { path: { type: 'string', required: true }, requestId: { type: 'string' }, query: { type: 'string' }, workstreamId: { type: 'string' }, cursor: { type: 'string' } } });
  projectTool(ctx, { name: 'project_delegate', method: 'delegate',
    description: 'Delegate actual work authorized by the current user. Supply the original workstreamId to continue its fixed worker Session. queued means not started. Preserve all restrictions in brief. readonly has no shell or repository writes; docs writes only declared repository document paths and Project deliverables. isolate is only for explicitly requested independent parallel development.',
    parameters: { replacesWorkstreamId: { type: 'string', description: 'Explicitly replace a truly failed, drained work for this same requirement; preserves the original member and failure history.' }, replacementReason: { type: 'string' }, requestId: { type: 'string', description: 'The whole user goal declared by project_request; settlement-driven next stages remain with this goal.' }, requestRevision: { type: 'number' }, blockedBy: { type: 'array', items: { type: 'string' }, description: 'Existing workstream IDs whose actual completion is required before this work starts.' }, workstreamId: { type: 'string' }, title: { type: 'string' }, brief: { type: 'string', required: true }, scope: { type: 'string', enum: ['readonly', 'docs', 'development'], required: true }, writePaths: { type: 'array', items: { type: 'string' } }, isolate: { type: 'boolean' } } });
  projectTool(ctx, { name: 'project_stop', method: 'stopTool', description: 'Stop one workstream and its owned activity; omit workstreamId only to stop all Project background work. This interrupts work, does not send another worker prompt, and does not automatically restart.', parameters: { workstreamId: { type: 'string' } } });
  ctx.systemPrompt.section({ name: 'project:scope', order: 10300, interpolate: false, text: ({ agent }) => ctx.get('projects')?.contextFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:charter', order: 10305, interpolate: false, text: ({ agent }) => ctx.get('projects')?.charterFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:decisions', order: 10315, interpolate: false, text: ({ agent }) => ctx.get('projects')?.decisionsFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:preferences', order: 10310, interpolate: false, text: ({ agent }) => ctx.get('projects')?.preferencesFor(agent?.id) ?? '' });
}
